# Resend (https://resend.com) — create a key under API Keys
RESEND_API_KEY=re_placeholder
# Must be on a domain verified in Resend (or onboarding@resend.dev while testing)
RESEND_FROM_EMAIL=Notely <hello@example.com>
# Public base URL used to build password reset links
APP_URL=http://localhost:3000
EOF
cat > src/lib/email.ts <<'EOF'
import { Resend } from "resend";

let client: Resend | undefined;

type Message = { to: string; subject: string; text: string; html: string };

const escapeHtml = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

// Never throws: a failed email must not break the request that triggered it.
async function send({ to, subject, text, html }: Message): Promise<boolean> {
  const apiKey = process.env.RESEND_API_KEY;
  const from = process.env.RESEND_FROM_EMAIL;
  if (!apiKey || !from) {
    console.warn(`[email] RESEND_API_KEY / RESEND_FROM_EMAIL not set; skipping "${subject}"`);
    return false;
  }
  try {
    client ??= new Resend(apiKey);
    const { error } = await client.emails.send({ from, to, subject, text, html });
    if (error) {
      console.error(`[email] Resend refused "${subject}": ${error.name}: ${error.message}`);
      return false;
    }
    return true;
  } catch (err) {
    console.error(`[email] failed to send "${subject}"`, err);
    return false;
  }
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  const name = escapeHtml(user.name);
  return send({
    to: user.email,
    subject: "Welcome to Notely",
    text: `Hi ${user.name},\n\nWelcome to Notely! Your account is ready.`,
    html: `<p>Hi ${name},</p><p>Welcome to Notely! Your account is ready.</p>`,
  });
}

export function sendPasswordResetEmail(user: { email: string; name: string }, resetUrl: string) {
  const name = escapeHtml(user.name);
  const url = escapeHtml(resetUrl);
  return send({
    to: user.email,
    subject: "Reset your Notely password",
    text: `Hi ${user.name},\n\nReset your password: ${resetUrl}\n\nThis link expires in 1 hour. If you didn't ask for it, ignore this email.`,
    html: `<p>Hi ${name},</p><p><a href="${url}">Reset your password</a></p><p>This link expires in 1 hour. If you didn't ask for it, ignore this email.</p>`,
  });
}
EOF
python3 - <<'EOF'
p='src/lib/users.ts'
s=open(p).read()
s='import { createHash, randomBytes, randomUUID } from "node:crypto";\nimport { sendPasswordResetEmail, sendWelcomeEmail } from "@/lib/email";\n\n'+s
s+='''
export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }
  const user: User = {
    id: randomUUID(),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// Only the SHA-256 of each token is stored, keyed by hash.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

/**
 * Emails a reset link if the address belongs to a user. Always resolves the same way
 * so callers can't use it to discover which emails are registered.
 */
export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email === email.trim().toLowerCase());
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  const base = process.env.APP_URL ?? "http://localhost:3000";
  await sendPasswordResetEmail(user, `${base}/reset-password?token=${token}`);
}

/** Validates and consumes a reset token (single use). Returns the user id, or undefined. */
export async function consumePasswordResetToken(token: string): Promise<string | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return entry.userId;
}
'''
open(p,'w').write(s)
EOF
